"""Картинка: множество Мандельброта как массив чисел."""
import numpy as np


def draw(fig):
    x, y = np.meshgrid(np.linspace(-2.2, 0.8, 240), np.linspace(-1.2, 1.2, 180))
    c = x + 1j * y
    z = np.zeros_like(c)
    steps = np.zeros(c.shape)
    for i in range(30):
        inside = np.abs(z) <= 2
        z[inside] = z[inside] ** 2 + c[inside]
        steps[inside] = i
    ax = fig.add_subplot()
    ax.imshow(steps, cmap="magma", extent=(-2.2, 0.8, -1.2, 1.2))
    ax.set_title("Множество Мандельброта")


if __name__ == "__main__":
    from mpldemo import run
    run(draw)
